func TestStringifyDate_StringPassesThrough(t *testing.T) {
	t.Parallel()
	if got := stringifyDate("2024-12-31"); got != "2024-12-31" {
		t.Errorf("expected '2024-12-31', got %q", got)
	}
}

func TestStringifyDate_NilReturnsEmpty(t *testing.T) {
	t.Parallel()
	if got := stringifyDate(nil); got != "" {
		t.Errorf("expected empty string for nil, got %q", got)
	}
}

// ── #13 Serializer drops nil/null fields (omitempty) ──

func TestSerialize_OmitsNilFields(t *testing.T) {
	t.Parallel()
	pet := models.NewPet("OmitTest", []string{"http://example.com/a.png"})
	data, err := serialize(pet)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	// Optional pointer fields with no value should be absent from the JSON.
	s := string(data)
	if strings.Contains(s, "\"id\":null") || strings.Contains(s, "\"status\":null") {
		t.Errorf("expected omitempty to drop nil fields, got %s", s)
	}
}

// ── Gap AJ: required non-nullable fields reject null/missing on deserialize ──

func TestDeserialize_RequiredFieldNullThrows(t *testing.T) {
	t.Parallel()
	raw := []byte(`{"name":null,"photoUrls":["u"]}`)
	var pet models.Pet
	err := deserialize(raw, &pet)
	if err == nil {
		t.Fatal("expected error when required non-nullable field 'name' is null")
	}
	msg := err.Error()
	if !strings.Contains(msg, "must not be null") && !strings.Contains(msg, "missing") {
		t.Errorf("expected error to mention null/missing for 'name', got: %v", err)
	}
}

func TestDeserialize_RequiredFieldMissingThrows(t *testing.T) {
	t.Parallel()
	raw := []byte(`{"photoUrls":["x"]}`)
	var pet models.Pet
	err := deserialize(raw, &pet)
	if err == nil {
		t.Fatal("expected error when required non-nullable field 'name' is missing")
	}
	msg := err.Error()
	if !strings.Contains(msg, "missing") && !strings.Contains(msg, "must not be null") {
		t.Errorf("expected error to mention missing 'name', got: %v", err)
	}
}

// ── #14 Deserializer ignores unknown fields ──

func TestDeserialize_IgnoresUnknownFields(t *testing.T) {
	t.Parallel()
	// Use a Pet payload with a bogus extra field. encoding/json should
	// silently drop it (no error, no mangled value).
	raw := []byte(`{"id":99,"name":"Skip","photoUrls":[],"bogusExtra":"keep-going"}`)
	var pet models.Pet
	if err := deserialize(raw, &pet); err != nil {
		t.Fatalf("expected unknown fields to be ignored, got %v", err)
	}
	if pet.Name != "Skip" {
		t.Errorf("expected name 'Skip', got %q", pet.Name)
	}
}

// ── model-equality-swift-go: Equal() value equality ──

func TestModelEqual_Identical(t *testing.T) {
	t.Parallel()
	id := int64(7)
	name := "Fido"
	a := models.Category{Id: &id, Name: &name}
	id2 := int64(7)
	name2 := "Fido"
	b := models.Category{Id: &id2, Name: &name2}
	if !a.Equal(b) {
		t.Errorf("expected equal Category values to compare equal")
	}
}

func TestModelEqual_Different(t *testing.T) {
	t.Parallel()
	name := "Fido"
	other := "Rex"
	a := models.Category{Name: &name}
	b := models.Category{Name: &other}
	if a.Equal(b) {
		t.Errorf("expected differing Category values to compare unequal")
	}
}

// A Pet carries slice/Set fields (PhotoUrls, Tags). The built-in `==` operator
// panics at runtime on such values; Equal() must compare them without panicking.
func TestModelEqual_SliceBearingModel(t *testing.T) {
	t.Parallel()
	a := models.Pet{Name: "Rex", PhotoUrls: models.Set[string]{"a", "b"}}
	b := models.Pet{Name: "Rex", PhotoUrls: models.Set[string]{"a", "b"}}
	if !a.Equal(b) {
		t.Errorf("expected slice-bearing Pet values to compare equal via Equal()")
	}
	c := models.Pet{Name: "Rex", PhotoUrls: models.Set[string]{"a", "c"}}
	if a.Equal(c) {
		t.Errorf("expected Pets with differing PhotoUrls to compare unequal")
	}
}

// A Metadata carries a map field (AdditionalProperties). A value of this type is
// not even comparable with `==` (it would fail to compile); Equal() must work.
func TestModelEqual_MapBearingModel(t *testing.T) {
	t.Parallel()
	a := models.Metadata{AdditionalProperties: map[string]any{"k": "v"}}
	b := models.Metadata{AdditionalProperties: map[string]any{"k": "v"}}
	if !a.Equal(b) {
		t.Errorf("expected map-bearing Metadata values to compare equal via Equal()")
	}
	c := models.Metadata{AdditionalProperties: map[string]any{"k": "w"}}
	if a.Equal(c) {
		t.Errorf("expected Metadata with differing AdditionalProperties to compare unequal")
	}
}

func TestResolveOneOf_ReturnsFirstMatch(t *testing.T) {
	t.Parallel()
	candidates := []func(any) (any, error){
		func(any) (any, error) { return nil, errors.New("variant A does not match") },
		func(data any) (any, error) { return data, nil },
	}
	result, err := resolveOneOf("payload", candidates)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if result != "payload" {
		t.Errorf("expected first matching variant, got %v", result)
	}
}

// A payload matching none of the declared variants is a contract violation and
// must fail loudly with a non-nil error rather than be silently returned as nil.
func TestResolveOneOf_ThrowsOnNoMatch(t *testing.T) {
	t.Parallel()
	candidates := []func(any) (any, error){
		func(any) (any, error) { return nil, errors.New("variant A does not match") },
		func(any) (any, error) { return nil, errors.New("variant B does not match") },
	}
	_, err := resolveOneOf(map[string]any{"unexpected": true}, candidates)
	if err == nil {
		t.Errorf("expected a non-nil error when no oneOf variant matched")
	}
}

func TestResolveAnyOf_ThrowsOnNoMatch(t *testing.T) {
	t.Parallel()
	candidates := []func(any) (any, error){
		func(any) (any, error) { return nil, errors.New("no match") },
	}
	_, err := resolveAnyOf(map[string]any{}, candidates)
	if err == nil {
		t.Errorf("expected a non-nil error when no anyOf variant matched")
	}
}
